  </header>

  <main class="contract-main">
    <!-- 계약 요약 -->
    <div class="summary-card">
      <h1 class="summary-title">크레이지샷 상품대여 전자계약서</h1>
      {#if reservation?.reservation_code}
        <div class="summary-item">
          <span class="summary-label">예약코드</span>
          <span class="summary-value">{reservation.reservation_code}</span>
        </div>
      {/if}
      {#if product}
        <div class="summary-item">
          <span class="summary-label">대여 상품</span>
          <span class="summary-value">{product.name}</span>
        </div>
      {/if}
      {#if reservation}
        <div class="summary-item">
          <span class="summary-label">대여 기간</span>
          <span class="summary-value">
            {formatDate(reservation.start_date)} ~ {formatDate(reservation.end_date)}
          </span>
        </div>
      {/if}
      {#if customer?.full_name}
        <div class="summary-item">
          <span class="summary-label">예약자</span>
          <span class="summary-value">{customer.full_name}</span>
        </div>
      {/if}
      {#if customer?.phone}
        <div class="summary-item">
          <span class="summary-label">전화번호</span>
          <span class="summary-value">{customer.phone}</span>
        </div>
      {/if}
      {#if customer?.email}
        <div class="summary-item">
          <span class="summary-label">이메일</span>
          <span class="summary-value">{customer.email}</span>
        </div>
      {/if}
    </div>

    <!-- 계약서 본문 — canvas / spreadsheet / flow 모드 분기 -->
    {#if isCanvasMode && canvasDoc}
      <!-- canvas 모드: 배경 이미지 + 좌표 기반 필드 오버레이 -->
      <div class="doc-section canvas-doc-section">
        {#if contract?.title}
          <h2 class="doc-title">{contract.title}</h2>
        {/if}
        <p class="canvas-hint">계약서를 확인하고 서명란에 서명해 주세요.</p>

        {#each canvasDoc.pages as page (page.id)}
          <!-- 페이지 컨테이너: aspect-ratio 박스 + position:relative 기반 -->
          <div
            class="canvas-page"
            style="padding-bottom: {(page.height / page.width) * 100}%"
          >
            <!-- 배경 이미지 -->
            <img
              src={page.imageUrl}
              alt="계약서 {canvasDoc.pages.indexOf(page) + 1}페이지"
              class="canvas-bg"
              loading="lazy"
            />

            <!-- 필드 오버레이 -->
            {#each canvasDoc.fields.filter((f) => f.pageId === page.id) as field (field.id)}
              <div
                class="canvas-field canvas-field-{field.type}"
                style="
                  left:   {(field.x / page.width) * 100}%;
                  top:    {(field.y / page.height) * 100}%;
                  width:  {(field.width / page.width) * 100}%;
                  height: {(field.height / page.height) * 100}%;
                "
              >
                {#if field.type === 'signature'}
                  <!-- 서명 필드: SignatureCanvas 인라인 배치 -->
                  <div class="canvas-sig-wrap">
                    <SignatureCanvas
                      width={field.width}
                      height={field.height}
                      onchange={handleSigChange}
                    />
                  </div>
                {:else if field.type === 'text'}
                  <!-- 텍스트 필드: 변수 치환 값 표시 -->
                  <span class="canvas-text-value">
                    {field.boundVariable ? (substitutionMap[field.boundVariable] ?? '') : ''}
                  </span>
                {:else if field.type === 'label'}
                  <!-- 라벨 필드: 고정 텍스트 -->
                  <span class="canvas-label-value">{field.label}</span>
                {:else if field.type === 'issuer-image'}
                  <!-- 발행자 서명·직인 이미지 — 읽기 전용, 시각적 배치만 -->
                  {#if field.imageUrl}
                    <img
                      src={field.imageUrl}
                      alt={field.label || '발행자 서명·직인 이미지'}
                      class="canvas-issuer-img"
                      draggable="false"
                    />
                  {/if}
                {/if}
              </div>
            {/each}
          </div>
        {/each}
      </div>
    {:else if isSpreadsheetMode && spreadsheetDoc}
      <!-- spreadsheet 모드: 시트를 HTML 표로 렌더링 (읽기 전용, SSR 안전) -->
      <div class="doc-section">
        {#if contract?.title}
          <h2 class="doc-title">{contract.title}</h2>
        {/if}
        <div class="spreadsheet-doc-content">
          {@html renderSpreadsheetToHtml(spreadsheetDoc)}
        </div>
      </div>
    {:else if contentBlocks.length > 0}
      <!-- flow 모드: TipTap contentBlocks 렌더링 -->
      <div class="doc-section">
        {#if contract?.title}
          <h2 class="doc-title">{contract.title}</h2>
        {/if}
        <div class="doc-content">
          {#each contentBlocks as block (block)}
            {#if isTiptapDocBlock(block)}
              <!-- tiptap-doc: generateHTML는 DOM(document) 의존 → browser 가드 필수 -->
              <!-- SSR(Vercel Node.js)에서 호출 시 "window is not defined" 크래시 발생 -->
              <div class="doc-block doc-block-tiptap">
                {#if browser}
                  {@html renderTiptapDocToHtml(block.doc)}
                {:else}
                  <div class="doc-loading">계약서 내용을 불러오는 중...</div>
                {/if}
              </div>
            {:else if block.type === 'text'}
              <div class="doc-block">{@html block.html}</div>
            {:else if block.type === 'html'}
              <div class="doc-block">{@html block.content}</div>
            {:else if block.type === 'divider'}
              <hr class="doc-divider" />
            {/if}
          {/each}
        </div>
      </div>
    {:else}
      <div class="pdf-placeholder">
        <p>계약서 내용을 준비 중입니다. 잠시 후 다시 시도해 주세요.</p>
      </div>
    {/if}

    <!-- 특약 조항 -->
    {#if specifications.length > 0}
      <div class="doc-section">
        <h2 class="doc-title">특약 조항</h2>
        <div class="spec-content">
          {#each specifications as spec (spec.key)}
            <div class="spec-row">
              <span class="spec-key">{spec.key}</span>
              <span class="spec-value">{spec.value}</span>
            </div>
          {/each}
        </div>
      </div>
    {/if}

    <!-- P8B-5: 발행자(갑) 서명·직인 렌더링 (flow 모드: 문서 최하단) -->
    {#if issuerSignatures.length > 0}
      <div class="doc-section issuer-sig-section">
        <h2 class="doc-title">발행자 서명</h2>
        <div class="issuer-sig-grid">
          {#each issuerSignatures as isig (isig.id)}
            <div class="issuer-sig-item">
              <span class="issuer-sig-label">
                {isig.signature_type === 'company_seal' ? '법인직인' : '발행자 서명'}
              </span>
              {#if isig.signature_image_url}
                <img
                  src={isig.signature_image_url}
                  alt={isig.signature_type === 'company_seal' ? '법인직인' : '발행자 서명'}
                  class="issuer-sig-img"
                />
              {:else}
                <div class="issuer-sig-placeholder">서명 이미지 없음</div>
              {/if}
            </div>
          {/each}
        </div>
      </div>
    {/if}

    <!-- 서명 폼 -->
    {#if !done}
      <div class="sign-section">
        <!-- 동의 체크박스 -->
        <label class="agree-label">
          <input
            type="checkbox"
            class="agree-check"
            bind:checked={agreed}
          />
          <span>
            위 계약서 내용을 모두 확인하였으며, 본 전자계약에 동의합니다.
          </span>
        </label>

        <!-- 전자 서명 캔버스 (flow 모드 전용 — canvas 모드는 위 페이지 내 인라인 서명) -->
        {#if !isCanvasMode}
          <div class="sig-section">
            <SignatureCanvas
              width={600}
              height={160}
              onchange={handleSigChange}
            />
          </div>
        {:else}
          <p class="canvas-sign-hint">위 계약서 서명란에 직접 서명해 주세요.</p>
        {/if}

        {#if signError}
          <p class="sign-error" role="alert">{signError}</p>
        {/if}

        <button
          class="btn-sign"
          onclick={submitSign}
          disabled={signing_ || !agreed || !sigValid}
        >
          {signing_ ? '서명 처리 중...' : '서명하기'}
        </button>
      </div>
    {:else}
      <div class="sign-done">
        <span class="done-icon">✅</span>
        <p>서명이 완료되었습니다. 잠시 후 이동합니다...</p>
      </div>
    {/if}
  </main>
</div>

<style>
  :global(body) {
    background: var(--cs-lilac, #ECEBF4);
    margin: 0;
  }

  .contract-page {
    min-height: 100dvh;
    display: flex;
    flex-direction: column;
  }

  /* 헤더 */
  .contract-header {
    background: var(--cs-dark, #100B32);
    padding: 16px 20px;
    display: flex;
    align-items: center;
  }
  .logo-svg {
    display: block;
  }

  /* 메인 — A4 폭 기준 */
  .contract-main {
    flex: 1;
    max-width: 210mm;
    margin: 0 auto;
    width: 100%;
    padding: 24px 20px 48px;
    display: flex;
    flex-direction: column;
    gap: 20px;
    box-sizing: border-box;
  }

  /* 요약 카드 */
  .summary-card {
    background: #fff;
    border-radius: 20px;
    padding: 24px;
    display: flex;
    flex-direction: column;
    gap: 12px;
  }
  .summary-title {
    font-size: 18px;
    font-weight: 700;
    color: var(--cs-dark, #100B32);
    margin: 0 0 4px;
  }
  .summary-item {
    display: flex;
    align-items: center;
    gap: 12px;
  }
  .summary-label {
    flex: 0 0 80px;
    font-size: 13px;
    color: #666;
    font-weight: 700;
  }
  .summary-value {
    font-size: 14px;
    color: var(--cs-dark, #100B32);
    font-weight: 600;
  }

  /* 계약서 본문 */
  .doc-section {
    background: #fff;
    border-radius: 20px;
    padding: 24px;
    display: flex;
    flex-direction: column;
    gap: 12px;
    position: relative; /* overlay 이미지 absolute 배치 기준점 */
  }
  .doc-title {
    font-size: 16px;
    font-weight: 700;
    color: var(--cs-dark, #100B32);
    margin: 0 0 4px;
  }
  .doc-content {
    display: flex;
    flex-direction: column;
    gap: 12px;
  }
  .doc-block {
    font-size: 14px;
    line-height: 1.7;
    color: var(--cs-dark, #100B32);
  }
  /*
   * overlay 이미지(position:absolute)가 이 블록을 기준으로 배치됨.
   *
   * ⛔ 2026-08-19 좌표계 원점 불일치 수정(1차 시도, 틀렸음 — 아래 2차로 정정) — 처음에는
   * "이 블록 자신에게 패딩을 주면 그 패딩만큼 내부 absolute 자식이 안쪽으로 밀릴 것"이라고
   * 가정하고 `padding: calc(20mm - 44px)`를 부여했다. 그런데 이건 CSS의 기본 동작과
   * 반대다 — position:absolute 자식은 가장 가까운 position:relative 조상의 "border box"
   * 모서리를 기준으로 배치되며, **그 조상 자신의 padding은 이 기준점에 전혀 영향을 주지
   * 않는다**(padding은 안쪽 콘텐츠만 밀어낼 뿐, 요소 자신의 테두리 위치 자체를 옮기지
   * 않음). 실측(Claude Browser, `offsetFromWrapBorderBox`)으로 직접 확인: 1차 수정을
   * 적용한 채로도 이미지는 여전히 `.doc-block-tiptap`의 border box 모서리 + 저장된
   * x/y만큼에 정확히 렌더링됐고, 새로 추가한 패딩은 이미지 위치에 아무 효과가 없었다
   * (텍스트만 안쪽으로 밀려 오히려 텍스트-이미지 간 새로운 불일치만 생겼다).
   *
   * ✅ 2차(진짜) 수정 — 같은 방법으로 CMS 에디터(`.ProseMirror{padding:20mm}`)도 함께
   * 실측한 결과, CMS도 이미지가 `.ProseMirror`의 padding이 아니라 **border box** 기준(=
   * `.cde-editor-content`와 거의 동일한 지점, 그 사이에 패딩이 없으므로)으로 렌더링되고
   * 있었다 — 즉 "20mm 안쪽 여백이 원점"이라는 1차 진단의 전제 자체가 틀렸고, CMS·미리보기
   * 모달·고객화면 전부 원래부터 "각자의 anchor 요소가 자기 페이지 컨테이너로부터 얼마나
   * 떨어져 있는가"만이 실제 변수였다. CMS는 `.ProseMirror`가 `.cde-editor-content`(=페이지)
   * 바로 안에 패딩 없이 앉아있어 오프셋이 0이지만, 이 고객 화면은 `.doc-block-tiptap` 이전에
   * `.contract-main`(20px)·`.doc-section`(24px) 패딩이 누적돼(좌 44px·상 48px·우 44px·
   * 하 72px) anchor의 border box 자체가 그만큼 안쪽에서 시작한다.
   * 수정: `margin`을 그 누적 패딩만큼 음수로 줘서 이 블록의 border box를 다시
   * `.contract-main`(페이지) 모서리까지 끌어낸 뒤(=오프셋 0, CMS와 동일 기준점 확보),
   * 텍스트 콘텐츠의 기존 시각적 여백은 잃지 않도록 동일한 크기를 `padding`으로 되돌려
   * 부여한다(margin -N + padding +N → 일반 흐름 콘텐츠의 화면 위치는 변화 없음, 반면
   * overlay 이미지의 기준점인 border box만 실제로 이동함 — padding은 border box 위치에
   * 영향 없다는 위 원리를 반대로 이용).
   */
  /*
   * ⛔ 2026-08-19 폭 불일치 수정("2번") — 35라운드로 겹치기 이미지의 좌표 원점은
   * CMS와 정합됐지만, 실측 결과 이미지가 여전히 CMS와 다른 문단 근처에 나타났다.
   * 원인은 좌표 원점이 아니라 "텍스트가 줄바꿈되는 폭 자체"가 CMS(.ProseMirror
   * 콘텐츠 폭 = 210mm − 20mm×2 = 170mm)와 이 화면(margin/padding 상쇄 후에도 여전히
   * .doc-content 컨테이너 폭 그대로, 약 706px ≈ 187mm)이 서로 달라 같은 y값이 서로
   * 다른 줄/문단에 도달하기 때문이었다 — 오버레이 이미지의 x/y는 절대 px값이라
   * "어느 문단 위에 찍히는가"는 전적으로 텍스트가 실제로 몇 번째 줄까지 내려갔는지에
   * 좌우된다. line-height(CMS 1.8 vs 이 화면 1.7)·font-weight(CMS는 --text-pc-body-14
   * 토큰이 700(Bold) 지정, 이 화면은 미지정=기본 400)도 줄 간격·글자폭에 영향을 주므로
   * 함께 맞춘다.
   * 수정: max-width로 콘텐츠 폭을 CMS와 동일한 170mm로 상한(패딩 88px를 더한
   * calc(170mm + 88px)를 border-box 폭 상한으로 지정 — 콘텐츠 폭만 170mm가 되도록
   * 역산, 위 좌표 원점 수정에 쓰인 margin/padding 값은 그대로 유지해 원점 정합은
   * 깨지지 않는다) + line-height 1.8 + font-weight 700으로 CMS `.ProseMirror`와
   * 동일하게 맞춤. max-width라 좁은(모바일) 화면에서는 자연스럽게 그보다 좁게
   * 줄어들 뿐 넘치지 않는다 — 다만 그런 좁은 화면에서는 애초에 CMS의 고정폭 데스크톱
   * 캔버스와 줄바꿈이 똑같아질 수 없다는 한계는 이 수정으로도 해소되지 않는다(좌표가
   * 고정 px값으로 저장되는 설계 자체의 한계).
   */
  .doc-block-tiptap {
    position: relative;
    margin: -48px -44px -72px -44px;
    padding: 48px 44px 72px 44px;
    max-width: calc(170mm + 88px);
    line-height: 1.8;
    font-weight: 700;
  }
  /*
   * CMS `.ProseMirror p { margin: 0 0 0.5em }`(=14px 기준 7px) 재현 — 이 화면은 문단
   * 하단 여백이 아예 0이라 문단 수가 누적될수록(13개 조항 기준 약 13×7≈91px) CMS보다
   * 콘텐츠가 압축돼, 폭·줄간격·굵기를 맞춘 뒤에도 같은 y값이 CMS보다 더 뒤쪽 문단에
   * 도달하는 잔여 오차의 원인이었다(실측: 폭만 맞췄을 때 CMS "제8조" 대비 이 화면은
   * "제10조" 근처로 여전히 2개 조항 어긋남). em이 아니라 CMS와 동일한 절대 px(7px)로
   * 지정 — line-height 등 다른 em 기준값과 섞여 계산되는 것을 피함.
   */
  .doc-block-tiptap :global(p) {
    margin: 0 0 7px;
  }
  /*
   * renderTiptapDocToHtml()이 표를 감싸는 래퍼 — 넓은 표가 A4 페이지(.contract-main) 폭
   * 밖으로 넘치지 않도록 표만 가로 스크롤(tiptapRender.ts 참고).
   */
  .doc-block-tiptap :global(.tt-table-scroll) {
    overflow-x: auto;
    max-width: 100%;
  }
  /*
   * TipTap 표(tiptap-doc content_blocks에서 생성) 기본 스타일 — 아래 cs-contract-table은
   * 레거시 ContentBlock 표용이라 TipTap이 생성한 <table>에는 적용되지 않아 고객 서명
   * 화면에서 표 서식이 소실된 것처럼 보였다(2026-08-15 실사용 중 발견,
   * ContractTemplatePreviewModal.svelte와 동일 수정).
   */
  .doc-block-tiptap :global(table) {
    border-collapse: collapse;
    width: 100%;
    margin: 0.5em 0;
  }
  .doc-block-tiptap :global(table th),
  .doc-block-tiptap :global(table td) {
    border: 1px solid #ddd;
    padding: 4px 6px;
    overflow-wrap: anywhere;
  }
  .doc-block-tiptap :global(table th) {
    background: #f6f6f6;
    font-weight: 700;
  }
  .doc-block :global(table.cs-contract-table) {
    width: 100%;
    border-collapse: collapse;
    font-size: 12px;
  }
  .doc-block :global(table.cs-contract-table th),
  .doc-block :global(table.cs-contract-table td) {
    border: 1px solid #DDDDDD;
    padding: 7px 10px;
    text-align: left;
  }
  .doc-block :global(table.cs-contract-table th) {
    background: #f6f6f6;
    color: #666;
    font-weight: 700;
    white-space: nowrap;
  }
  /* SSR 중 tiptap-doc 로딩 플레이스홀더 */
  .doc-loading {
    font-size: 13px;
    color: #888;
    padding: 8px 0;
  }
  .doc-divider {
    border: none;
    border-top: 1px solid var(--cs-lilac, #ECEBF4);
    margin: 4px 0;
  }
  .pdf-placeholder {
    background: #fff;
    border-radius: 20px;
    padding: 40px 20px;
    text-align: center;
    color: #888;
    font-size: 14px;
  }

  /* 특약 조항 */
  .spec-content {
    display: flex;
    flex-direction: column;
    gap: 8px;
  }
  .spec-row {
    display: flex;
    gap: 12px;
    padding: 8px 0;
    border-bottom: 1px solid var(--cs-lilac, #ECEBF4);
