    word-break: break-word;
  }
  .spec-value {
    flex: 1;
    color: var(--cs-dark, #100B32);
    white-space: pre-wrap;
    word-break: break-word;
  }

  /* 서명 섹션 */
  .sign-section {
    background: #fff;
    border-radius: 20px;
    padding: 24px;
    display: flex;
    flex-direction: column;
    gap: 16px;
  }
  .agree-label {
    display: flex;
    align-items: flex-start;
    gap: 10px;
    cursor: pointer;
    font-size: 14px;
    color: var(--cs-dark, #100B32);
    line-height: 1.5;
  }
  .agree-check {
    width: 18px;
    height: 18px;
    flex-shrink: 0;
    margin-top: 2px;
    accent-color: var(--cs-red-badge, #FF3535);
    cursor: pointer;
  }

  /* 서명 캔버스 영역 */
  .sig-section {
    display: flex;
    flex-direction: column;
    gap: 8px;
  }
  .sign-error {
    font-size: 13px;
    color: var(--cs-red-badge, #FF3535);
    margin: 0;
  }
  .btn-sign {
    width: 100%;
    height: 54px;
    background: var(--cs-red-badge, #FF3535);
    color: #fff;
    border: none;
    border-radius: 30px;
    font-size: 16px;
    font-weight: 700;
    cursor: pointer;
    transition: background 0.15s;
    min-height: 54px;
  }
  .btn-sign:hover:not(:disabled) { background: var(--cs-red, #CF0000); }
  .btn-sign:disabled {
    background: #ccc;
    cursor: not-allowed;
  }

  /* P8B-5: 발행자 서명 렌더링 */
  .issuer-sig-section { margin-top: 0; }
  .issuer-sig-grid {
    display: flex;
    gap: 24px;
    flex-wrap: wrap;
    margin-top: 8px;
  }
  .issuer-sig-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    padding: 16px;
    background: #f9f9f9;
    border-radius: 12px;
    min-width: 120px;
  }
  .issuer-sig-label {
    font-size: 12px;
    font-weight: 600;
    color: #666;
    text-align: center;
  }
  .issuer-sig-img {
    max-width: 120px;
    max-height: 80px;
    object-fit: contain;
  }
  .issuer-sig-placeholder {
    width: 120px;
    height: 60px;
    background: #eee;
    border-radius: 8px;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: 12px;
    color: #999;
  }

  /* 서명 완료 */
  .sign-done {
    background: #fff;
    border-radius: 20px;
    padding: 32px 24px;
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 12px;
    text-align: center;
  }
  .done-icon { font-size: 40px; }
  .sign-done p { font-size: 15px; color: var(--cs-dark, #100B32); font-weight: 600; margin: 0; }

  /* ── canvas 모드 ──────────────────────────────────── */
  .canvas-doc-section { padding: 16px; }

  .canvas-hint, .canvas-sign-hint {
    font-size: 13px;
    color: #666;
    margin: 0 0 8px;
  }
  .canvas-sign-hint { margin: 0; }

  /* 페이지 aspect-ratio 박스 */
  .canvas-page {
    position: relative;
    width: 100%;
    overflow: hidden;
    border: 1px solid #e0e0e0;
    border-radius: 8px;
    background: #fff;
    margin-bottom: 12px;
  }

  /* 배경 이미지: 절대 배치로 박스 전체 채움 */
  .canvas-bg {
    position: absolute;
    inset: 0;
    width: 100%;
    height: 100%;
    object-fit: contain;
    display: block;
  }

  /* 필드 공통 — 절대 배치, 퍼센트 좌표 */
  .canvas-field {
    position: absolute;
    box-sizing: border-box;
    display: flex;
    align-items: center;
    justify-content: flex-start;
    overflow: hidden;
  }

  /* 서명 필드 */
  .canvas-field-signature {
    border: 2px dashed var(--cs-purple, #3B2F8A);
    border-radius: 4px;
    background: rgba(59, 47, 138, 0.04);
  }
  .canvas-sig-wrap {
    width: 100%;
    height: 100%;
    display: flex;
    align-items: stretch;
  }
  /* SignatureCanvas가 필드 크기에 맞게 늘어나도록 */
